using Microsoft.EntityFrameworkCore;
using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
internal static class MailUpdateSpecs
{
 public static async Task Run(string folder,Action<string,bool> check){var root=Path.Combine(folder,"mail-update-specs");Directory.CreateDirectory(root);var factory=new DatabaseFactory(new AppSettings{SqlitePath=Path.Combine(root,"mail.db")});await factory.InitializeAsync();var receipt=new DateTime(2026,10,20,22,44,0);var body="Доступна новая версия DSM с новыми функциями. Войдите в NAS_TEST и перейдите в Панель управления > Обновить и восстановить для установки DSM 7.4.1-90080 Update 1. Подробнее об обновлениях DSM. Из NAS_TEST";var mail=new MailReport("fixture","notice1","reports@example.test","[NAS_TEST] Обнаружено новое обновление DSM для NAS_TEST",body,receipt,"",receipt);var profile=new KeywordProfile{Provider="DSM"};MailUpdates.Defaults(profile);
 check("DSM update sample recognized by default dictionary",MailUpdates.Matches(profile,mail));var extracted=MailUpdates.Extract(mail,"DSM","DSM");check("DSM complete version includes hyphen update number and terminal punctuation",extracted.Version=="7.4.1-90080 Update 1");
 check("DSM same normalized version has stable key",MailUpdates.Extract(mail with{Body=body.Replace("Update 1","обновление 1")},"DSM","DSM").Key==extracted.Key);
 check("Backup success mail is not an update",!MailUpdates.Matches(profile,mail with{Subject="Backup completed",Body="Резервное копирование DSM успешно"}));
 check("Ambiguous available versions never guessed",MailUpdates.Extract(mail with{Body="DSM 7.3.1 и DSM 7.4.1"},"DSM","DSM").Version=="");
 var qnap=new KeywordProfile{Provider="QNAP"};MailUpdates.Defaults(qnap);check("QNAP generic firmware mail requires product marker",!MailUpdates.Matches(qnap,mail with{Subject="New firmware version",Body="Router version 1.2.3"}));check("QNAP QTS update recognized",MailUpdates.Matches(qnap,mail with{Subject="New firmware version for QNAP",Body="QTS 5.2.1.2930"}));check("QuTS hero version extracted",MailUpdates.Extract(mail with{Body="QuTS hero h5.2.1.2930"},"QNAP","QTS").Version=="h5.2.1.2930");
 int deviceId;await using(var db=factory.Create()){var d=new Device{Name="NAS_TEST",Type="Synology NAS",Status="ONLINE",CheckedAt=DateTime.Now};db.Devices.Add(d);await db.SaveChangesAsync();deviceId=d.Id;}
 var store=new ReportStore(factory);await store.IngestAsync(mail);ReportEvent seed;await using(var db=factory.Create()){seed=await db.Reports.AsNoTracking().SingleAsync();check("Update mail enters review without creating a backup or incident",seed.MailCategory=="Update"&&seed.UpdateVersion==extracted.Version&&seed.IsPending&&seed.JobId==null&&await db.Jobs.CountAsync()==0&&await db.Incidents.CountAsync()==0);}
 var request=new MailBindRequest(seed.Id,TargetKind.Device,deviceId,"",true,true,true,false,null,RemoteData.EntityStamp(seed),SubjectLines:"[NAS_TEST]\nОбнаружено новое обновление DSM",MailCategory:"Update",UpdateProduct:"DSM");var preview=await MailBinding.PreviewAsync(factory,request);check("Update binding preview uses existing AND subject matcher",preview.Matched==1&&preview.ConflictingRules.Length==0);await MailBinding.ApplyAsync(factory,request with{PreviewToken=preview.Token});
 await using(var db=factory.Create()){var report=await db.Reports.SingleAsync();var rule=await db.Rules.SingleAsync();var view=await MailUpdateStore.ViewAsync(db,deviceId,CancellationToken.None);check("Bound update has no job and separate version metadata",report.DeviceId==deviceId&&report.JobId==null&&report.MailCategory=="Update"&&!report.IsPending&&rule.MailCategory=="Update"&&view.Items is [{InstalledUtc:null,Version:"7.4.1-90080 Update 1"}]);check("Update mail cannot create device error lamp",await db.Incidents.CountAsync()==0&&(await DeviceProblems.OpenAsync(db,deviceId)).Length==0);}
 await store.IngestAsync(mail with{Key="notice2",ImapReceivedAt=receipt.AddMinutes(5)});var network=new NetworkState();await using(var db=factory.Create()){var d=await db.Devices.SingleAsync();check("Repeated version stored once across distinct mails",MailUpdates.Parse(d.MailUpdatesJson).Length==1&&await db.Reports.CountAsync()==2);MailUpdateStore.Capture(network,[d]);MailUpdateStore.Capture(network,[d]);check("Mail update availability does not queue Telegram",network.Notifications.Count==0);check("Mail update icon independent of healthy device lamp",MailUpdates.Overview(d.OsUpdatesJson,d.MailUpdatesJson)?.HasUpdates==true&&DashboardState.Device(d,[],DateTime.Now,30,true).Lamp==LampState.Green);
 network.Notifications.Add(new(){EntityKey="mail-updates:"+deviceId+":"+extracted.Key,Title="legacy update"});var view=await MailUpdateStore.ViewAsync(db,deviceId,CancellationToken.None);await MailUpdateStore.ConfirmAsync(db,new(deviceId,view.Items[0].Key,view.Hash),"fixture-admin",CancellationToken.None);MailUpdateStore.Capture(network,[d]);check("Installed mark cancels unsent notification",network.Notifications[0].HandledAt!=null);}
 await store.IngestAsync(mail with{Key="notice3",ImapReceivedAt=receipt.AddMinutes(10)});await using(var db=factory.Create()){var d=await db.Devices.SingleAsync();check("Previously installed version cannot reopen from repeated mail",MailUpdates.Parse(d.MailUpdatesJson) is [{InstalledUtc:not null}]&&MailUpdates.Overview(d.OsUpdatesJson,d.MailUpdatesJson)==null);}
 await store.IngestAsync(mail with{Key="notice4",Body=body.Replace("Update 1","Update 2"),ImapReceivedAt=receipt.AddHours(1)});await using(var db=factory.Create()){var d=await db.Devices.SingleAsync();var rows=MailUpdates.Parse(d.MailUpdatesJson);MailUpdateStore.Capture(network,[d]);check("Newer version restores update icon and notification",rows.Length==2&&rows.Count(x=>x.InstalledUtc==null)==1&&MailUpdates.Overview("",d.MailUpdatesJson)?.HasUpdates==true&&network.Notifications.All(n=>n.HandledAt!=null));check("Update mail never creates jobs or incidents",await db.Jobs.CountAsync()==0&&await db.Incidents.CountAsync()==0);}
 bool stale=false;await using(var db=factory.Create()){try{await MailUpdateStore.ConfirmAsync(db,new(deviceId,extracted.Key,"stale"),"test",CancellationToken.None);}catch(InvalidOperationException){stale=true;}}check("Installed confirmation rejects stale list",stale);
 // Even after raw email is removed by retention, acknowledgements live with device metadata.
 await using(var db=factory.Create()){db.Intake.RemoveRange(db.Intake);db.Pending.RemoveRange(db.Pending);db.MailSources.RemoveRange(db.MailSources);db.Reports.RemoveRange(db.Reports);await db.SaveChangesAsync();}await store.IngestAsync(mail with{Key="notice5",ImapReceivedAt=receipt.AddHours(2)});await using(var db=factory.Create()){check("Email retention cannot erase installed version acknowledgement",MailUpdates.Parse((await db.Devices.SingleAsync()).MailUpdatesJson).Single(x=>x.Key==extracted.Key).InstalledUtc!=null);var p=await db.Profiles.SingleAsync(p=>p.Provider=="DSM");p.UpdateSubjectTerms="custom update phrase";p.UpdateBodyTerms="";await db.SaveChangesAsync();await MailUpdateStore.SeedAsync(db,CancellationToken.None);check("Repeated initialization preserves edited update dictionary",p.UpdateSubjectTerms=="custom update phrase"&&p.UpdateBodyTerms=="");}
 var originalStamp=RemoteData.EntityStamp(new Device{Id=1,Name="d"});check("Mail update metadata does not conflict with device editing",originalStamp==RemoteData.EntityStamp(new Device{Id=1,Name="d",MailUpdatesJson="changed"}));
 bool rejected=false;await using(var db=factory.Create()){var e=await db.Reports.AsNoTracking().SingleAsync();try{await MailBinding.PreviewAsync(factory,new(e.Id,TargetKind.SqlJob,123,"",true,false,false,false,null,RemoteData.EntityStamp(e),MailCategory:"Update",UpdateProduct:"DSM"));}catch(ArgumentException){rejected=true;}}check("Update mail cannot bind to backup job",rejected);
 await store.IngestAsync(mail with{Key="subject-only",Subject=mail.Subject+" DSM 7.4.1-90080 Update 3",Body="",ImapReceivedAt=receipt.AddHours(3)});await MailBinding.ReanalyzeDeviceAsync(factory,deviceId);ReportEvent subjectOnly;await using(var db=factory.Create()){subjectOnly=await db.Reports.AsNoTracking().SingleAsync(e=>e.UpdateVersion=="7.4.1-90080 Update 3");check("Subject-only retained update can be reanalyzed",!subjectOnly.IsPending&&!subjectOnly.Issue.Contains("не сохранён"));}
 int secondId;await using(var db=factory.Create()){var d=new Device{Name="NAS_2"};db.Devices.Add(d);await db.SaveChangesAsync();secondId=d.Id;}
 var move=new MailBindRequest(subjectOnly.Id,TargetKind.Device,secondId,"",true,false,false,true,null,RemoteData.EntityStamp(subjectOnly),MailCategory:"Update",UpdateProduct:"DSM");await MailBinding.ApplyAsync(factory,move);await using(var db=factory.Create()){var old=await db.Devices.SingleAsync(d=>d.Id==deviceId);var next=await db.Devices.SingleAsync(d=>d.Id==secondId);check("Moving update mail withdraws old device notice and keeps new binding",MailUpdates.Parse(old.MailUpdatesJson).Single(x=>x.Key==subjectOnly.UpdateKey).Withdrawn&&MailUpdates.Parse(next.MailUpdatesJson).Single().Withdrawn==false);}

 }
}
